// ============================================================================
// B) OPTIMAL TIKTOK SHOP "TEST & DOUBLE-DOWN" RULE:
// 1. Test Phase: Run each 'approved' product for 3 to 5 videos (rotating across products).
// 2. Auto-Pause Losers ('paused'): If a product has >= 4 videos AND max views < 1,000 AND total orders == 0,
//    automatically mark it for status='paused' and skip it!
// 3. Scale Winners ('winner'): If a product has status='winner' OR any video >= 5,000 views OR orders_est >= 1,
//    promote it to 'winner' and keep producing 2-3 new hook variations per week indefinitely!
// ============================================================================

const statsByProduct = new Map();
for (const p of products) {
  const pKey = p.product_key;
  const qCount = queueRows.filter(q => q.product_key === pKey).length;
  const pPosts = postRows.filter(r => r.product_key === pKey);
  const maxViews = pPosts.reduce((m, r) => Math.max(m, Number(r.views || 0)), 0);
  const totalOrders = pPosts.reduce((s, r) => s + Number(r.orders_est || 0), 0);
  const isAutoWinner = p.status === 'winner' || maxViews >= 5000 || totalOrders >= 1;
  const isAutoLoser = !isAutoWinner && qCount >= 4 && maxViews < 1000 && totalOrders === 0;
  statsByProduct.set(pKey, {
    qCount,
    maxViews,
    totalOrders,
    isAutoWinner,
    isAutoLoser,
    effectiveStatus: isAutoWinner ? 'winner' : (isAutoLoser ? 'paused' : String(p.status || 'candidate'))
  });
}

// Eligible pool: 'winner' (unlimited videos) + 'approved' (in 3-5 video test phase, i.e. < 4 videos)
const eligibleProducts = products.filter(p => {
  const st = statsByProduct.get(p.product_key);
  return st && (st.effectiveStatus === 'winner' || (st.effectiveStatus === 'approved' && st.qCount < 4));
});

// Sort by lowest video count first so every approved product gets its 1st, 2nd, 3rd, 4th test video evenly, while winners interleave
eligibleProducts.sort((a, b) => {
  const sa = statsByProduct.get(a.product_key);
  const sb = statsByProduct.get(b.product_key);
  return (sa.qCount - sb.qCount);
});

